class PriceStreak {
  private prices: number[] = [];

  next(price: number): number {
    this.prices.push(price);
    let i = this.prices.length - 1;
    while (i >= 0 && this.prices[i] <= price) i--;
    return this.prices.length - 1 - i;
  }
}

